// План: specs/ui-style.md, тест 2.1. Тикет #ceb80d (עבר QA 17.11.2026). Только просмотр → @prod-safe.
import { test, expect } from '../../fixtures';
import { HINT, openAllCards } from './helpers';

test.describe('כל הכרטיסים — סגנון חדש', () => {
  test('כל הכרטיסים: רקע המסך בהיר (לא כחול כהה), הנחיית ההצמדה בכרטיס עם רקע לבן @prod-safe #ceb80d', async ({ asUser }) => {
    const client = await asUser('client'); // 0500000004
    await openAllCards(client);

    const res = await client.evaluate(
      ({ hint }) => {
        const norm = (s: string | null) => (s || '').replace(/\s+/g, ' ').trim();
        const parse = (c: string) => {
          const m = /^rgba?\(\s*(\d+),\s*(\d+),\s*(\d+)(?:,\s*([\d.]+))?\s*\)$/.exec(c);
          if (!m) return null;
          const a = m[4] === undefined ? 1 : parseFloat(m[4]);
          return a > 0.95 ? [+m[1], +m[2], +m[3]] : null; // только непрозрачный фон
        };
        const opaqueUp = (start: Element | null) => {
          for (let n = start; n; n = n.parentElement) {
            const rgb = parse(getComputedStyle(n).backgroundColor);
            if (rgb) return { el: n, rgb };
          }
          return null;
        };
        const hintEl = Array.from(document.body.querySelectorAll('*')).find(
          (e) => e.children.length === 0 && norm(e.textContent) === hint,
        );
        if (!hintEl) return { error: 'нет подсказки' };
        const hr = hintEl.getBoundingClientRect();

        // Фон экрана: точка у левого края на уровне подсказки (вне карточек).
        const screen = opaqueUp(document.elementFromPoint(2, hr.y + hr.height / 2));
        // Карточка подсказки: первый непрозрачный предок, начиная с родителя.
        const card = opaqueUp(hintEl.parentElement);
        if (!screen || !card) return { error: 'не найден непрозрачный фон' };
        const cr = card.el.getBoundingClientRect();
        const lum = ([r, g, b]: number[]) => (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255;
        return {
          screenRgb: screen.rgb,
          screenLum: lum(screen.rgb),
          cardRgb: card.rgb,
          sameEl: screen.el === card.el,
          cardWider: cr.width > hr.width + 1 && cr.height >= hr.height,
        };
      },
      { hint: HINT },
    );

    expect(res.error, res.error).toBeUndefined();
    // Фон экрана светлый, не тёмно-синий.
    expect(res.screenLum, `фон экрана ${JSON.stringify(res.screenRgb)} тёмный`).toBeGreaterThan(0.8);
    // Подсказка в отдельной белой карточке.
    expect(res.sameEl, 'подсказка не в отдельной карточке').toBe(false);
    expect(res.cardWider, 'карточка не охватывает подсказку').toBe(true);
    expect(res.cardRgb).toEqual([255, 255, 255]);
    await expect(client.getByText(HINT)).toBeVisible();
  });
});
